-- Explicit dedicated project only. Existing confirmed account; every fixture write rolls back.
begin;
select set_config('request.jwt.claim.sub',(select id::text from auth.users where email_confirmed_at is not null order by created_at desc limit 1),true);
set local role authenticated;
do $$declare v_page uuid;v_lead uuid;v_second uuid;v_third uuid;v_change uuid;v_prior uuid;v_req uuid=gen_random_uuid();v_stamp timestamptz;v_f uuid;v_day date=(clock_timestamp() at time zone 'UTC')::date;v_data jsonb;v_attempts bigint;v_archives bigint;v_followups bigint;v_calls bigint;begin
 v_attempts=(public.workspace_leads(null,'attempts')->>'total')::bigint;v_archives=(public.workspace_leads(null,'archive')->>'total')::bigint;v_followups=(public.workspace_followups(v_day)->>'total')::bigint;select calls_made into v_calls from public.daily_activity(v_day);
 v_page=public.manage_page(null,'Phase 4 test','',false);
 insert into public.leads(page_id,business_name,phone) values(v_page,'Workflow business','+12025550191') returning id,updated_at into v_lead,v_stamp;
 v_change=public.record_call(v_lead,v_stamp,v_req,'no_answer','First attempt');
 if public.record_call(v_lead,v_stamp,v_req,'no_answer','First attempt')<>v_change then raise exception 'Retry not idempotent';end if;
 if (select total_attempts from public.lead_attempt_summary where lead_id=v_lead)<>1 or (public.workspace_leads(v_page)->>'total')::int<>0 or (public.workspace_leads(null,'attempts')->>'total')::int<>v_attempts+1 then raise exception 'First failed call routing wrong';end if;
 raise notice 'PASS: Confirmed server-timestamped attempt is idempotent and routes exclusively to Attempts';
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_prior=public.record_call(v_lead,v_stamp,gen_random_uuid(),'voicemail','Second');
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_change=public.record_call(v_lead,v_stamp,gen_random_uuid(),'no_answer','Third');
 if not exists(select 1 from public.leads where id=v_lead and archive_reason='attempts_exhausted' and purge_after is null) then raise exception 'Three failure archive wrong';end if;
 if (public.workspace_leads(null,'attempts')->>'total')::int<>v_attempts or (public.workspace_leads(null,'archive')->>'total')::int<>v_archives+1 then raise exception 'Exhausted duplicated in workflow';end if;
 raise notice 'PASS: Three unsuccessful attempts archive as Exhausted without rejection retention';
 perform public.undo_workflow(v_change);
 perform public.undo_workflow(v_change);
 if (select total_attempts from public.lead_attempt_summary where lead_id=v_lead)<>2 or exists(select 1 from public.leads where id=v_lead and archived_at is not null) then raise exception 'Attempt undo failed';end if;
 if (select calls_made from public.daily_activity(v_day))<>v_calls+2 or (select count(*) from public.call_attempts where lead_id=v_lead)<>3 then raise exception 'Corrected attempts counted or history deleted';end if;
 raise notice 'PASS: Undo is idempotent, preserves original history and corrects counts/status/workflow';
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_change=public.record_call(v_lead,v_stamp,gen_random_uuid(),'interested','Connected');
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_change=public.record_call(v_lead,v_stamp,gen_random_uuid(),'no_answer','One new failure');
 if (select consecutive_failed_attempts from public.lead_attempt_summary where lead_id=v_lead)<>1 or exists(select 1 from public.leads where id=v_lead and archived_at is not null) then raise exception 'Successful connection did not reset failure streak';end if;
 raise notice 'PASS: Successful conversation resets consecutive failure limit';
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_change=public.record_call(v_lead,v_stamp,gen_random_uuid(),'callback_requested','Discuss pricing',v_day+1,'14:30');
 select id into v_f from public.followups where lead_id=v_lead and completed_at is null and cancelled_at is null;
 if v_f is null or (public.workspace_leads(v_page)->>'total')::int<>0 or (public.workspace_followups(v_day)->>'total')::int<>v_followups+1 then raise exception 'Callback routing failed';end if;
 if not exists(select 1 from public.followups where id=v_f and scheduled_time='14:30') then raise exception 'Literal schedule shifted';end if;
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_prior=public.manage_followup(v_lead,v_stamp,gen_random_uuid(),v_f,'schedule',v_day+2,'09:15','Updated note');
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_change=public.manage_followup(v_lead,v_stamp,gen_random_uuid(),v_f,'complete');
 if (public.workspace_leads(v_page)->>'total')::int<>1 or not exists(select 1 from public.followups where id=v_f and completed_at is not null) then raise exception 'Complete routing failed';end if;
 perform public.undo_workflow(v_change);
 if not exists(select 1 from public.followups where id=v_f and completed_at is null and scheduled_date=v_day+2 and scheduled_time='09:15' and notes='Updated note') then raise exception 'Completion undo lost schedule';end if;
 perform public.undo_workflow(v_prior);
 if not exists(select 1 from public.followups where id=v_f and scheduled_time='14:30' and notes='Discuss pricing') then raise exception 'Sequential follow-up undo failed';end if;
 raise notice 'PASS: Follow-ups persist, reschedule, complete and undo with literal date/time and notes';
 select updated_at into v_stamp from public.leads where id=v_lead;
 v_change=public.record_call(v_lead,v_stamp,gen_random_uuid(),'interested','Follow-up conversation',null,null,v_f);
 if not exists(select 1 from public.followups where id=v_f and completed_at is not null and completion_outcome='interested') then raise exception 'Follow-up outcome not completed atomically';end if;
 raise notice 'PASS: Follow-up outcome records one attempt and completes the task atomically';
 insert into public.leads(page_id,business_name,phone) values(v_page,'Rejected local','0300 555 0191') returning id,updated_at into v_second,v_stamp;
 v_change=public.record_call(v_second,v_stamp,gen_random_uuid(),'not_interested','Do not call');
 insert into public.leads(page_id,business_name,phone) values(v_page,'Same phone retained','03005550191') returning id,updated_at into v_third,v_stamp;
 if not public.is_lead_suppressed(v_third) or not exists(select 1 from public.leads where id=v_third) then raise exception 'Local DNC suppression or retention failed';end if;
 begin perform public.record_call(v_third,v_stamp,gen_random_uuid(),'no_answer');raise exception 'Suppressed call accepted';exception when insufficient_privilege then null;end;
 perform public.undo_workflow(v_change);
 if public.is_lead_suppressed(v_third) or exists(select 1 from public.leads where id=v_second and archived_at is not null) then raise exception 'Accidental rejection correction failed';end if;
 raise notice 'PASS: Local phone DNC blocks outreach without deduplication; explicit correction releases only its source';
 select updated_at into v_stamp from public.leads where id=v_third;
 perform public.save_lead(v_third,v_stamp,'{"status":"voicemail"}');
 if not exists(select 1 from public.leads where id=v_third and status='voicemail') then raise exception 'Manual status routing failed';end if;
 select id into v_change from public.workflow_changes where lead_id=v_third and undone_at is null order by sequence desc limit 1;
 perform public.undo_workflow(v_change);
 if not exists(select 1 from public.leads where id=v_third and status='new') then raise exception 'Status correction failed';end if;
 begin update public.leads set status='not_interested' where id=v_third;raise exception 'Direct status bypass accepted';exception when insufficient_privilege then null;end;
 begin insert into public.call_attempts(lead_id,outcome) values(v_third,'no_answer');raise exception 'Direct attempt bypass accepted';exception when insufficient_privilege then null;end;
 begin insert into public.followups(lead_id,scheduled_date) values(v_third,v_day);raise exception 'Direct follow-up bypass accepted';exception when insufficient_privilege then null;end;
 raise notice 'PASS: Status changes are reversible; direct workflow mutation bypasses are denied';
 v_data=public.workspace_activity(v_day);
 if jsonb_array_length(v_data->'rows')=0 or (v_data->>'total')::int<=0 then raise exception 'Activity missing';end if;
 v_data=public.workspace_overview(v_day);
 if jsonb_array_length(v_data->'daily')<>7 then raise exception 'Overview weekly history missing';end if;
 perform set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000006',true);
 if exists(select 1 from public.workflow_changes where lead_id=v_lead) or exists(select 1 from public.call_attempts where lead_id=v_lead) then raise exception 'Cross-owner history read accepted';end if;
 begin perform public.workspace_lead_history(v_lead);raise exception 'Cross-owner history RPC accepted';exception when insufficient_privilege then null;end;
 begin perform public.undo_workflow(v_change);raise exception 'Cross-owner undo accepted';exception when insufficient_privilege then null;end;
 begin perform public.record_call(v_lead,v_stamp,gen_random_uuid(),'no_answer');raise exception 'Cross-owner call accepted';exception when insufficient_privilege then null;end;
 raise notice 'PASS: Real activity/overview read models and cross-owner write isolation';
end $$;
reset role;
select json_build_object('suite','workflows','passed',true,'fixtures','transaction rollback') as verification;
rollback;
